/// the attributes the input type's rules give it and its errors; a nested
/// object's in a fieldset, and a list's rows with their buttons. `form` is
/// a new form when the page passes none, and `choices` turns a text or
/// number field the app names into a select.
#[component]
pub async fn create_tenant_input_fields(
    #[default(CreateTenantInputForm::new())] form: CreateTenantInputForm,
    #[default] errors: FormErrors,
    #[default] choices: Choices,
) -> topcoat::Result<impl View> {
    let form_errors = errors.unshown(CreateTenantInputForm::shows);
    Ok(view! {
        for message in form_errors {
            <p class="form-error">(message)</p>
        }
        <div class="field">
            <label for="create-tenant-input-name">"Name"</label>
            match choices.of("name", "name") {
                Some(options) => choice_select(id: "create-tenant-input-name", name: "name", required: true, invalid: errors.invalid("name"), options: choice_options(options, form.name.as_deref())),
                None => <input id="create-tenant-input-name" name="name" type="text" required=(true) minlength="2" maxlength="80" value=(form.name.clone()) aria-invalid=(errors.invalid("name"))>,
            }
            for message in errors.of("name") {
                <p class="field-error">(message)</p>
            }
        </div>
        <div class="field">
            <label for="create-tenant-input-slug">"Slug"</label>
            match choices.of("slug", "slug") {
                Some(options) => choice_select(id: "create-tenant-input-slug", name: "slug", required: true, invalid: errors.invalid("slug"), options: choice_options(options, form.slug.as_deref())),
                None => <input id="create-tenant-input-slug" name="slug" type="text" required=(true) minlength="1" maxlength="255" value=(form.slug.clone()) aria-invalid=(errors.invalid("slug"))>,
            }
            for message in errors.of("slug") {
                <p class="field-error">(message)</p>
            }
        </div>
    })
}

